```python
import re
import uuid
import datetime

_ALLOWED_CONTENT_TYPES = frozenset({"image/jpeg", "image/png"})
_MAX_BYTES = 5 * 1024 * 1024
_SAFE_CHARS = re.compile(r"[^A-Za-z0-9._-]")


def init_db(conn) -> None:
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key) -> int:
    uploaded_at = datetime.datetime.now(datetime.timezone.utc).isoformat()
    cur = conn.cursor()
    try:
        cur.execute(
            "INSERT INTO photos (title, description, s3_key, uploaded_at) "
            "VALUES (?, ?, ?, ?)",
            (title, description, s3_key, uploaded_at),
        )
        new_id = cur.lastrowid
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return int(new_id)


def search_photos(conn, term) -> list:
    cur = conn.cursor()
    cur.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos "
        "WHERE instr(lower(title), lower(?)) > 0 "
        "OR instr(lower(description), lower(?)) > 0 "
        "ORDER BY id ASC",
        (term, term),
    )
    rows = cur.fetchall()
    return [
        {
            "id": row[0],
            "title": row[1],
            "description": row[2],
            "s3_key": row[3],
            "uploaded_at": row[4],
        }
        for row in rows
    ]


def _safe_name(filename: str) -> str:
    # Strip any directory components for both POSIX and Windows separators.
    base = filename.replace("\\", "/").rsplit("/", 1)[-1]
    if base in ("", ".", ".."):
        raise ValueError("filename has no usable base name")
    return _SAFE_CHARS.sub("_", base)


def upload_photo(s3, bucket, filename, data, content_type) -> str:
    if content_type not in _ALLOWED_CONTENT_TYPES:
        raise ValueError("unsupported content type")
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")
    if len(data) > _MAX_BYTES:
        raise ValueError("data exceeds 5 MiB limit")

    safe = _safe_name(filename)
    key = f"photos/{uuid.uuid4().hex}/{safe}"
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600) -> str:
    if isinstance(expires, bool) or not isinstance(expires, int):
        raise ValueError("expires must be an integer number of seconds")
    if expires < 1 or expires > 3600:
        raise ValueError("expires must be between 1 and 3600 seconds")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type) -> int:
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        try:
            s3.delete_object(Bucket=bucket, Key=key)
        except Exception:
            # Cleanup failed; the original metadata error is still the one reported.
            pass
        raise
